    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceHostOps = UniffiVTableCallbackInterfaceHostOps(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeHostOps.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface HostOps: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeHostOps.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface HostOps: handle missing in uniffiClone")
            }
